  const runtimeRef = useRef<any>(null);
  const draftsRef = useRef<Record<string, string>>({});

  const switchThread = async (id: string) => {
    if (currentThreadIdRef.current === id) return; // 避免重复切换

    const prevId = currentThreadIdRef.current;
    if (prevId) {
      try {
        const text = runtimeRef.current?.thread?.composer?.getState()?.text;
        if (typeof text === 'string') {
          draftsRef.current[prevId] = text;
        }
      } catch (e) { /* ignore */ }
    }

    setThreadId(id);
    const [dbMsgs, runs] = await Promise.all([
      window.cukoAPI.getMessages(id),
      Promise.resolve(window.cukoAPI.getRuns?.()).catch(() => [] as any[]),
    ]);
    // ... 加载 msgs 等

    // 延迟恢复草稿，等 React 渲染完成、内部状态重置后再恢复
    setTimeout(() => {
      try {
        const draft = draftsRef.current[id] || '';
        runtimeRef.current?.thread?.composer?.setText(draft);
      } catch (e) { /* ignore */ }
    }, 50);
  };
```
